{"action":"edit","path":"toolformer_filter.py","old_text":"","new_text":"import numpy as np

def filter_api_calls(with_result, call_only, no_call, tau_filter):
    # Validate inputs
    if isinstance(tau_filter, bool):
        raise ValueError("tau_filter cannot be a boolean")
    if not np.isscalar(tau_filter):
        raise ValueError("tau_filter must be a scalar")
    if not np.isfinite(tau_filter):
        raise ValueError("tau_filter must be finite")
    if tau_filter < 0:
        raise ValueError("tau_filter must be nonnegative")

    for arr, name in [(with_result, 'with_result'), (call_only, 'call_only'), (no_call, 'no_call')]:
        if not isinstance(arr, np.ndarray):
            raise ValueError(f"{name} must be a numpy array")
        if arr.ndim != 2:
            raise ValueError(f"{name} must be a 2D matrix")
        if not np.all(np.isfinite(arr)):
            raise ValueError(f"{name} contains non-finite values")
        if np.any(arr > 0):
            raise ValueError(f"{name} contains positive values")

    if not (with_result.shape == call_only.shape == no_call.shape):
        raise ValueError("All input matrices must have the same shape")

    n_candidates, horizon = with_result.shape

    # Compute normalized weights
    t = np.arange(horizon, dtype=float)
    raw_weights = np.maximum(0.0, 1.0 - 0.2 * t)
    if raw_weights.sum() == 0:
        norm_weights = np.ones(horizon) / horizon if horizon > 0 else np.array([])
    else:
        norm_weights = raw_weights / raw_weights.sum()

    # Compute weighted losses (lower is better)
    L_plus = -np.dot(with_result, norm_weights)
    L_call_only = -np.dot(call_only, norm_weights)
    L_empty = -np.dot(no_call, norm_weights)

    L_minus = np.minimum(L_empty, L_call_only)
    margins = L_minus - L_plus
    keep_mask = margins >= tau_filter

    return keep_mask, margins
